//! Port of `src/terminal/snapshot/hyperlink.zig`.
//!
//! STATUS: ported
//!
//! Snapshot hyperlink entry encoding.
//!
//! Each entry contains a URI and either an implicit numeric ID or an explicit
//! byte-string ID. Implicit IDs are generated by the terminal when the source
//! hyperlink has no explicit ID. A record can use these entries to build a
//! hyperlink table and assign indexes according to that record's format.
//! Indexing and ordering are properties of the containing record rather than
//! this codec.
//!
//! URIs and explicit IDs are non-empty arbitrary byte strings. Their lengths
//! are retained on the wire; they are not NUL-terminated and need not contain
//! UTF-8. Native page storage requires every allocated hyperlink string to
//! contain at least one byte. Encoding and standalone decoding reject empty
//! strings; PAGE decoding consumes but ignores entries it cannot represent.
//!
//! All integers are unsigned and little-endian.
//!
//! ## Implicit ID
//!
//! | Offset | Size      | Field              |
//! | -----: | --------: | :----------------- |
//! |      0 |         1 | Kind, `1`          |
//! |      1 |         4 | Implicit ID (`u32`) |
//! |      5 |         4 | URI length (`u32`) |
//! |      9 | `uri_len` | URI bytes          |
//!
//! ## Explicit ID
//!
//! | Offset       | Size      | Field                      |
//! | -----------: | --------: | :------------------------- |
//! |            0 |         1 | Kind, `2`                  |
//! |            1 |         4 | Explicit ID length (`u32`) |
//! |            5 |  `id_len` | Explicit ID bytes          |
//! | `5 + id_len` |         4 | URI length (`u32`)         |
//! | `9 + id_len` | `uri_len` | URI bytes                  |
//!
//! Both variants have nine bytes of fixed overhead. The remaining bytes are
//! the URI plus the explicit ID, when present.
//!
//! The standalone decoder returns an owned hyperlink. PAGE decoding reads
//! strings directly into the destination page's allocator instead.

use std::borrow::Cow;

use super::io::{self, Error};
use crate::terminal::hyperlink::{self as terminal_hyperlink, Hyperlink, HyperlinkId, PageEntry, PageEntryId};
use crate::terminal::page::Page;
use crate::terminal::size::{self as terminal_size, OffsetSlice};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
enum Kind {
    Implicit = 1,
    Explicit = 2,
}

impl Kind {
    fn from_int(v: u8) -> Option<Kind> {
        match v {
            1 => Some(Kind::Implicit),
            2 => Some(Kind::Explicit),
            _ => None,
        }
    }
}

/// Errors possible while encoding one hyperlink entry: `WriteFailed`,
/// `InvalidUri` (a native URI must contain at least one byte),
/// `InvalidExplicitId` (a native explicit ID must contain at least one
/// byte), `StringTooLong` (a string does not fit the version 1 length field).
pub type EncodeError = Error;

/// Errors possible while decoding one owned hyperlink entry: read errors,
/// `OutOfMemory`, `InvalidKind`, `InvalidUri`, `InvalidExplicitId`.
pub type DecodeError = Error;

/// Errors possible while decoding directly into a native page: read errors
/// and `InvalidKind`.
pub type DecodePageError = Error;

/// Encode one hyperlink entry.
pub fn encode(value: &Hyperlink<'_>, writer: &mut dyn io::Writer) -> Result<(), EncodeError> {
    // Validate the complete value before writing any part of this variable-
    // length entry. This keeps callers able to roll back at entry boundaries.
    if value.uri.is_empty() {
        return Err(Error::InvalidUri);
    }
    if value.uri.len() > u32::MAX as usize {
        return Err(Error::StringTooLong);
    }
    if let HyperlinkId::Explicit(id) = &value.id {
        if id.is_empty() {
            return Err(Error::InvalidExplicitId);
        }
        if id.len() > u32::MAX as usize {
            return Err(Error::StringTooLong);
        }
    }

    match &value.id {
        HyperlinkId::Implicit(id) => {
            writer.write_byte(Kind::Implicit as u8)?;
            io::write_int::<u32>(writer, *id)?;
            io::write_int::<u32>(writer, value.uri.len() as u32)?;
            writer.write_all(&value.uri)?;
        }
        HyperlinkId::Explicit(id) => {
            writer.write_byte(Kind::Explicit as u8)?;
            io::write_int::<u32>(writer, id.len() as u32)?;
            writer.write_all(id)?;
            io::write_int::<u32>(writer, value.uri.len() as u32)?;
            writer.write_all(&value.uri)?;
        }
    }
    Ok(())
}

fn alloc_bytes(len: usize) -> Result<Vec<u8>, Error> {
    let mut buf = Vec::new();
    buf.try_reserve_exact(len).map_err(|_| Error::OutOfMemory)?;
    buf.resize(len, 0);
    Ok(buf)
}

/// Decode one owned hyperlink entry.
pub fn decode(reader: &mut dyn io::Reader) -> Result<Hyperlink<'static>, DecodeError> {
    let kind_raw = reader.take_byte()?;
    let kind = Kind::from_int(kind_raw).ok_or(Error::InvalidKind)?;

    match kind {
        Kind::Implicit => {
            let id = io::read_int::<u32>(reader)?;
            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Err(Error::InvalidUri);
            }

            let mut uri = alloc_bytes(uri_len)?;
            reader.read_slice_all(&mut uri)?;

            Ok(Hyperlink {
                id: HyperlinkId::Implicit(id),
                uri: Cow::Owned(uri),
            })
        }

        Kind::Explicit => {
            let id_len = io::read_int::<u32>(reader)? as usize;
            if id_len == 0 {
                return Err(Error::InvalidExplicitId);
            }

            let mut id = alloc_bytes(id_len)?;
            reader.read_slice_all(&mut id)?;

            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Err(Error::InvalidUri);
            }

            let mut uri = alloc_bytes(uri_len)?;
            reader.read_slice_all(&mut uri)?;

            Ok(Hyperlink {
                id: HyperlinkId::Explicit(Cow::Owned(id)),
                uri: Cow::Owned(uri),
            })
        }
    }
}

/// `decodePageString` failure: either the page string storage is full or
/// the reader failed.
enum PageStringError {
    StringsOutOfMemory,
    Read(Error),
}

impl From<Error> for PageStringError {
    fn from(e: Error) -> Self {
        PageStringError::Read(e)
    }
}

/// Free a string allocated by `decode_page_string`.
fn free_page_string(page: &mut Page, value: OffsetSlice<u8>) {
    let mem = page.memory;
    // SAFETY: `value` was allocated from this page's string allocator.
    unsafe { page.string_alloc.free(mem, value.slice_ptr(mem)) };
}

/// Decode one hyperlink directly into page-owned storage.
///
/// Explicit ID and URI bytes are read into the page string allocator and the
/// completed entry is inserted into the page hyperlink set. The returned ID is
/// the native ID assigned by the destination page. Zero is returned when the
/// encoded value cannot be represented within the destination page, including
/// empty strings and insufficient advertised capacity.
pub fn decode_page(page: &mut Page, reader: &mut dyn io::Reader) -> Result<terminal_hyperlink::Id, DecodePageError> {
    let kind_raw = reader.take_byte()?;
    let kind = Kind::from_int(kind_raw).ok_or(Error::InvalidKind)?;

    let entry: PageEntry = match kind {
        Kind::Implicit => {
            let id = io::read_int::<u32>(reader)?;
            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Ok(0);
            }

            let uri = match decode_page_string(page, reader, uri_len) {
                Ok(v) => v,
                Err(PageStringError::StringsOutOfMemory) => {
                    reader.discard_all(uri_len)?;
                    return Ok(0);
                }
                Err(PageStringError::Read(e)) => return Err(e),
            };

            PageEntry {
                id: PageEntryId::Implicit(id),
                uri,
            }
        }

        Kind::Explicit => {
            let id_len = io::read_int::<u32>(reader)? as usize;
            if id_len == 0 {
                let uri_len = io::read_int::<u32>(reader)? as usize;
                reader.discard_all(uri_len)?;
                return Ok(0);
            }

            let id = match decode_page_string(page, reader, id_len) {
                Ok(v) => v,
                Err(PageStringError::StringsOutOfMemory) => {
                    reader.discard_all(id_len)?;
                    let uri_len = io::read_int::<u32>(reader)? as usize;
                    reader.discard_all(uri_len)?;
                    return Ok(0);
                }
                Err(PageStringError::Read(e)) => return Err(e),
            };

            let uri_len = match io::read_int::<u32>(reader) {
                Ok(v) => v as usize,
                Err(e) => {
                    free_page_string(page, id);
                    return Err(e);
                }
            };
            if uri_len == 0 {
                free_page_string(page, id);
                return Ok(0);
            }

            let uri = match decode_page_string(page, reader, uri_len) {
                Ok(v) => v,
                Err(PageStringError::StringsOutOfMemory) => {
                    let discarded = reader.discard_all(uri_len);
                    free_page_string(page, id);
                    discarded?;
                    return Ok(0);
                }
                Err(PageStringError::Read(e)) => {
                    free_page_string(page, id);
                    return Err(e);
                }
            };

            PageEntry {
                id: PageEntryId::Explicit(id),
                uri,
            }
        }
    };

    let ctx = terminal_hyperlink::SetContext::new(page as *mut Page);
    // SAFETY: all access goes through `ctx.page` (the live destination page).
    let added = unsafe { (*ctx.page).hyperlink_set.add_context((*ctx.page).memory, entry, &ctx) };
    match added {
        Ok(id) => Ok(id),
        Err(_) => {
            // The entry was fully consumed, so capacity failure only loses this
            // optional hyperlink. Free its strings and let cells restore unlinked.
            // SAFETY: the entry's strings were allocated in this page.
            unsafe { entry.free(page as *mut Page) };
            Ok(0)
        }
    }
}

fn decode_page_string(
    page: &mut Page,
    reader: &mut dyn io::Reader,
    len: usize,
) -> Result<OffsetSlice<u8>, PageStringError> {
    debug_assert!(len > 0);

    // Allocate space for the string and read directly into it.
    let mem = page.memory;
    // SAFETY: `mem` is the page base.
    let value = unsafe { page.string_alloc.alloc::<u8>(mem, len) }.map_err(|_| PageStringError::StringsOutOfMemory)?;
    // SAFETY: `value` was just allocated with `len` bytes.
    let bytes = unsafe { &mut *value };
    if let Err(e) = reader.read_slice_all(bytes) {
        // SAFETY: allocated above from the same allocator.
        unsafe { page.string_alloc.free(mem, value) };
        return Err(PageStringError::Read(e));
    }

    Ok(OffsetSlice::new(
        terminal_size::get_offset(mem, value.cast::<u8>().cast_const()),
        len,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::terminal::page::Capacity;
    use crate::terminal::snapshot::fixture;
    use crate::terminal::snapshot::io::{FixedReader, FixedWriter, Reader as _};

    fn implicit_fixture() -> Vec<u8> {
        fixture::parse(include_str!("testdata/hyperlink-implicit-v1.hex"))
    }
    fn explicit_fixture() -> Vec<u8> {
        fixture::parse(include_str!("testdata/hyperlink-explicit-v1.hex"))
    }

    #[test]
    fn golden_implicit_encoding() {
        let value = Hyperlink {
            id: HyperlinkId::Implicit(0x01020304),
            uri: Cow::Borrowed(b"uri"),
        };

        let mut buf = [0u8; 128];
        let mut writer = FixedWriter::new(&mut buf);
        encode(&value, &mut writer).unwrap();

        let reference = implicit_fixture();
        fixture::expect_equal(
            fixture::Kind::Bytes,
            "src/terminal/snapshot/testdata/hyperlink-implicit-v1.hex",
            "snapshot_fixture-hyperlink-implicit-v1.hex",
            &reference,
            writer.buffered(),
        );

        let mut reader = FixedReader::new(&reference);
        let decoded = decode(&mut reader).unwrap();
        assert_eq!(value, decoded);
    }

    #[test]
    fn golden_explicit_encoding() {
        let value = Hyperlink {
            id: HyperlinkId::Explicit(Cow::Borrowed(b"id")),
            uri: Cow::Borrowed(b"uri"),
        };

        let mut buf = [0u8; 128];
        let mut writer = FixedWriter::new(&mut buf);
        encode(&value, &mut writer).unwrap();

        let reference = explicit_fixture();
        fixture::expect_equal(
            fixture::Kind::Bytes,
            "src/terminal/snapshot/testdata/hyperlink-explicit-v1.hex",
            "snapshot_fixture-hyperlink-explicit-v1.hex",
            &reference,
            writer.buffered(),
        );

        let mut reader = FixedReader::new(&reference);
        let decoded = decode(&mut reader).unwrap();
        assert_eq!(value, decoded);
    }

    #[test]
    fn encode_rejects_invalid_strings_before_writing() {
        let cases: [(Hyperlink<'static>, Error); 3] = [
            (
                Hyperlink {
                    id: HyperlinkId::Implicit(1),
                    uri: Cow::Borrowed(b""),
                },
                Error::InvalidUri,
            ),
            (
                Hyperlink {
                    id: HyperlinkId::Explicit(Cow::Borrowed(b"")),
                    uri: Cow::Borrowed(b"uri"),
                },
                Error::InvalidExplicitId,
            ),
            (
                Hyperlink {
                    id: HyperlinkId::Explicit(Cow::Borrowed(b"id")),
                    uri: Cow::Borrowed(b""),
                },
                Error::InvalidUri,
            ),
        ];

        for (value, expected) in cases {
            let mut encoded = [0u8; 32];
            let mut writer = FixedWriter::new(&mut encoded);
            assert_eq!(Err(expected), encode(&value, &mut writer));
            assert_eq!(0, writer.end);
        }
    }

    #[test]
    fn decode_rejects_empty_strings() {
        let cases: [(&[u8], Error); 3] = [
            (b"\x01\x04\x03\x02\x01\x00\x00\x00\x00", Error::InvalidUri),
            (b"\x02\x00\x00\x00\x00", Error::InvalidExplicitId),
            (b"\x02\x02\x00\x00\x00id\x00\x00\x00\x00", Error::InvalidUri),
        ];

        for (fixture, expected) in cases {
            let mut reader = FixedReader::new(fixture);
            assert_eq!(Some(expected), decode(&mut reader).err());
        }
    }

    #[test]
    fn decode_page_ignores_empty_strings() {
        let fixtures: [&[u8]; 3] = [
            b"\x01\x04\x03\x02\x01\x00\x00\x00\x00",
            b"\x02\x00\x00\x00\x00\x03\x00\x00\x00uri",
            b"\x02\x02\x00\x00\x00id\x00\x00\x00\x00",
        ];

        for fixture in fixtures {
            let mut page = Page::init(Capacity {
                cols: 1,
                rows: 1,
                hyperlink_bytes: 512,
                string_bytes: 16,
                ..Default::default()
            })
            .unwrap();

            let mut reader = FixedReader::new(fixture);
            assert_eq!(0, decode_page(&mut page, &mut reader).unwrap());
            assert_eq!(0, page.hyperlink_set.count());
            assert_eq!(Err(Error::EndOfStream), reader.take_byte());
        }
    }

    #[test]
    fn decode_rejects_invalid_kinds() {
        for kind in [0u8, 3, u8::MAX] {
            let fixture = [kind];
            let mut reader = FixedReader::new(&fixture);
            assert_eq!(Some(Error::InvalidKind), decode(&mut reader).err());
        }
    }

    // Zig's "decode allocation failure" injects allocator failures with
    // `std.testing.FailingAllocator`. The port decodes into global-allocator
    // vectors (allocation failure aborts), so that test is not ported.

    #[test]
    fn reject_every_truncation() {
        let fixtures = [implicit_fixture(), explicit_fixture()];

        for fixture in &fixtures {
            for fixture_len in 0..fixture.len() {
                let mut reader = FixedReader::new(&fixture[..fixture_len]);
                assert_eq!(Some(Error::EndOfStream), decode(&mut reader).err());
            }
        }
    }
}
